// ==== public/js/health-standing-controller.js ====
(() => {
(() => {
    function select(deps, selector) {
        return deps.root.querySelector(selector) || deps.select(selector);
    }
    function documentSelect(deps, selector) {
        return deps.document.querySelector(selector) || deps.select(selector);
    }
    function healthStandingRef(deps, refAge) {
        const value = Number(refAge || deps.state.healthStandingRef || 20);
        return Number.isFinite(value) ? value : 20;
    }
    function inputValue(deps, selector) {
        return documentSelect(deps, selector)?.value ?? "";
    }
    function render(data, deps) {
        const wrap = select(deps, "#hStanding");
        if (!wrap)
            return;
        wrap.innerHTML = CairnHealthStanding.renderHealthStandingHtml(data, { referenceAge: deps.state.healthStandingRef });
        // If the whole-picture conductor already leads the Standing page, do not render
        // a second "one lever" surface from the narrower health read.
        if (select(deps, "#cfocusStandingSlot .cfocus"))
            wrap.querySelector(".hstand-lever")?.remove();
        wrap.querySelectorAll("[data-refage]").forEach((button) => button.addEventListener("click", () => {
            deps.state.healthStandingRef = Number(button.dataset.refage || 20);
            load(deps, deps.pollToken(), deps.state.healthStandingRef);
        }));
        wrap.querySelector("[data-lever-go]")?.addEventListener("click", () => {
            deps.state.meSeg = "health";
            deps.state.healthSeg = "markers";
            deps.state.healthSegPicked = true;
            deps.activateTab("me");
        });
        select(deps, "#bpLogOpen")?.addEventListener("click", () => openBpSheet(deps));
        void deps.loadDexaTargeting?.("hDexaSlot");
    }
    function openBpSheet(deps) {
        if (deps.document.getElementById("bpSheetOv"))
            return;
        const ov = deps.document.createElement("div");
        ov.id = "bpSheetOv";
        ov.className = "bpsheet-ov";
        ov.innerHTML = `<div class="bpsheet" role="dialog" aria-modal="true" aria-label="Log blood pressure">
      <div class="bpsheet-hd"><h3>Log a reading</h3><button class="xbtn bpsheet-x" type="button" aria-label="Close">✕</button></div>
      <form id="bpSheetForm" class="bpsheet-form">
        <div class="bpsheet-row">
          <label>Systolic<input id="bpSys" class="form-input" type="number" inputmode="numeric" min="60" max="260" placeholder="120" required></label>
          <label>Diastolic<input id="bpDia" class="form-input" type="number" inputmode="numeric" min="35" max="160" placeholder="80" required></label>
          <label>Pulse<input id="bpPulse" class="form-input" type="number" inputmode="numeric" min="25" max="240" placeholder="60"></label>
        </div>
        <label class="bpsheet-when">When<input id="bpAt" class="form-input" type="datetime-local" value="${deps.escapeAttr(CairnHealthStanding.localDateTimeInputValue())}"></label>
        <div class="bpsheet-row">
          <label>Position<input id="bpPosition" class="form-input" type="text" maxlength="40" placeholder="Seated"></label>
          <label>Note<input id="bpNote" class="form-input" type="text" maxlength="240" placeholder="Optional"></label>
        </div>
        <div class="bpsheet-ft"><button class="ghostbtn" type="button" data-close>Cancel</button><button class="logbtn" type="submit">Save</button></div>
      </form>
    </div>`;
        deps.document.body.appendChild(ov);
        const onKey = (event) => {
            if (event.key === "Escape")
                teardown();
        };
        function teardown() {
            deps.document.removeEventListener("keydown", onKey);
            ov.remove();
        }
        deps.document.addEventListener("keydown", onKey);
        ov.querySelector(".bpsheet-x")?.addEventListener("click", teardown);
        ov.querySelector("[data-close]")?.addEventListener("click", teardown);
        ov.addEventListener("click", (event) => {
            if (event.target === ov)
                teardown();
        });
        documentSelect(deps, "#bpSheetForm")?.addEventListener("submit", async (event) => {
            event.preventDefault();
            const form = event.currentTarget instanceof HTMLFormElement ? event.currentTarget : null;
            const submit = form?.querySelector("button[type='submit']") || null;
            if (submit)
                submit.disabled = true;
            const payload = {
                systolic: inputValue(deps, "#bpSys"),
                diastolic: inputValue(deps, "#bpDia"),
                pulse: inputValue(deps, "#bpPulse"),
                measured_at: inputValue(deps, "#bpAt"),
                position: inputValue(deps, "#bpPosition"),
                note: inputValue(deps, "#bpNote"),
                source: "manual",
            };
            try {
                const res = await deps.api("/blood-pressure", {
                    method: "POST",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify(payload),
                });
                if (!res || res.error) {
                    deps.toast(res?.error || "Couldn't log BP");
                    if (submit)
                        submit.disabled = false;
                    return;
                }
                deps.toast("BP logged");
                deps.swrInvalidate("markers:");
                teardown();
                load(deps, deps.pollToken(), deps.state.healthStandingRef || 20);
            }
            catch {
                deps.toast("Couldn't log BP");
                if (submit)
                    submit.disabled = false;
            }
        });
        setTimeout(() => documentSelect(deps, "#bpSys")?.focus(), 30);
    }
    function load(deps, token, refAge) {
        const ref = healthStandingRef(deps, refAge);
        deps.state.healthStandingRef = ref;
        deps.api(`/health/standing?reference_age=${encodeURIComponent(String(ref))}`)
            .then((data) => {
            if (token === deps.pollToken())
                render((data || null), deps);
        })
            .catch(() => {
            if (token !== deps.pollToken())
                return;
            const wrap = select(deps, "#hStanding");
            if (wrap)
                wrap.innerHTML = `<div class="hstand hstand-panel"><div class="empty">Couldn't load health standing right now.</div></div>`;
        });
    }
    function paintReview(deps) {
        const content = select(deps, "#hContent");
        if (!content)
            return;
        content.innerHTML = `<div id="hStanding"><div class="hstand hstand-busy"><div class="hshimmer hshimmer-lg"></div><div class="hshimmer"></div><div class="hshimmer hshimmer-sm"></div></div></div>
    <button type="button" class="hread-jump" id="hStandingToRead">
      <span class="hread-jump-main">
        <span class="lbl">Your whole picture</span>
        <span class="hread-jump-title">The full health read</span>
        <span class="hread-jump-sub">Synthesis, the connected-brain list, recovery, markers and supplements — read as one story.</span>
      </span>
      <span class="hread-jump-arrow" aria-hidden="true">→</span>
    </button>`;
        load(deps, deps.pollToken(), deps.state.healthStandingRef || 20);
        select(deps, "#hStandingToRead")?.addEventListener("click", () => openRead(deps));
    }
    function openRead(deps, opts = {}) {
        deps.state.meSeg = "health";
        deps.state.healthSeg = "read";
        deps.state.healthSegPicked = true;
        if (opts.scroll)
            deps.state.pendingHealthScroll = opts.scroll;
        deps.activateTab("me");
    }
    const CAIRN_HEALTH_STANDING_CONTROLLER = {
        load,
        openBpSheet,
        openRead,
        paintReview,
        render,
    };
    Object.assign(globalThis, { CairnHealthStandingController: CAIRN_HEALTH_STANDING_CONTROLLER });
    if (typeof window !== "undefined") {
        window.CairnHealthStandingController = CAIRN_HEALTH_STANDING_CONTROLLER;
    }
})();
})();
;
// ==== public/js/health-picture-client.js ====
(() => {
// @ts-check
// Pure Health picture/review rendering helpers for the vanilla PWA.
(() => {
    function asObject(value) {
        return value && typeof value === "object" ? value : null;
    }
    // review.parsed may arrive as a JSON string or an object.
    function parsedReview(review) {
        if (!review || review.error)
            return null;
        let parsed = review.parsed;
        if (typeof parsed === "string") {
            try {
                parsed = JSON.parse(parsed);
            }
            catch {
                parsed = null;
            }
        }
        return parsed && typeof parsed === "object" ? parsed : null;
    }
    // flag/status -> dot modifier. Colors mirror the marker flag pills:
    // low/high -> warn, "watch" -> gold, normal -> sage, none -> neutral hairline.
    function healthDotClass(flag) {
        const f = String(flag || "").toLowerCase();
        if (f === "low" || f === "high" || f === "abnormal" || f === "critical")
            return "hdot-warn";
        if (f === "normal" || f === "ok")
            return "hdot-ok";
        return f ? "hdot-watch" : "hdot-mute";
    }
    function reviewBusyHtml() {
        return `<div class="hpic hpic-busy">
    <div class="hpic-top"><span class="lbl">Your picture</span><span class="hpic-when">reviewing…</span></div>
    <div class="hshimmer hshimmer-lg"></div>
    <div class="hshimmer"></div>
    <div class="hshimmer hshimmer-sm"></div>
    <div class="hpic-busynote">Reading every record and trend — this can take a few minutes. You can keep using Cairn.</div>
  </div>`;
    }
    function healthHeroHtml(errorHtml) {
        return `<div class="hpic hpic-hero reveal" style="${stagger(0)}">
    <div class="artile artile-lg hpic-hero-art">${CairnHealthClient.HEALTH_HERO_ART}</div>
    <div class="hpic-hero-title">Build your whole picture</div>
    <div class="hpic-hero-sub">Share your bloodwork or a DEXA scan and Cairn reads it — markers, trends, and a coach's-eye view of what to do next.</div>
    ${String(errorHtml || "")}
    <button id="hHeroShare" class="logbtn hpic-cta-btn">SHARE A DOCUMENT</button>
  </div>`;
    }
    function buildPictureHtml(errorHtml, docCount) {
        const n = Number(docCount) || 0;
        return `<div class="hpic hpic-build reveal" style="${stagger(0)}">
    <span class="lbl">Your picture</span>
    <div class="hpic-headline">Your records are in.</div>
    <div class="hpic-hero-sub">One review across ${n === 1 ? "your document" : `all ${n} documents`} — what's strong, what to watch, and what to do this week.</div>
    ${String(errorHtml || "")}
    <button id="hRevBtn" class="logbtn hpic-cta-btn">BUILD MY PICTURE</button>
  </div>`;
    }
    function reviewHtml(review, stale, errorHtml) {
        const parsed = parsedReview(review) || {};
        const latestISO = latestReviewDate(parsed);
        const hz = (text) => escHtml(humanizeReviewText(String(text || ""), latestISO));
        const focus = (Array.isArray(parsed.focus) ? parsed.focus : [])
            .map(asObject)
            .filter((item) => !!item && !!(item.title || item.action))
            .map((item) => `
    <div class="hfocus">
      ${item.title ? `<div class="hfocus-title">${hz(item.title)}</div>` : ""}
      ${item.why ? `<div class="hfocus-why">${hz(item.why)}</div>` : ""}
      ${item.action ? `<div class="hfocus-act">→ ${hz(item.action)}</div>` : ""}
    </div>`)
            .join("");
        const watch = (Array.isArray(parsed.watchlist) ? parsed.watchlist : [])
            .map(asObject)
            .filter((item) => !!item && !!(item.marker || item.why))
            .map((item) => `
    <div class="hwatch">
      <span class="hdot ${healthDotClass(item.status)}"></span>
      <div class="hwatch-main">
        <div class="hwatch-line"><span class="hwatch-name">${escHtml(item.marker || "")}</span>${item.status ? `<span class="hwatch-st">${escHtml(item.status)}</span>` : ""}</div>
        ${item.why ? `<div class="hwatch-why">${hz(item.why)}</div>` : ""}
        ${item.action ? `<div class="hwatch-act">${hz(item.action)}</div>` : ""}
      </div>
    </div>`)
            .join("");
        const wins = (Array.isArray(parsed.wins) ? parsed.wins : [])
            .filter(Boolean)
            .map((win) => `<li>${hz(win)}</li>`)
            .join("");
        const followups = (Array.isArray(parsed.followups) ? parsed.followups : [])
            .map(asObject)
            .filter((item) => !!item && !!item.what)
            .map((item) => `
    <div class="hfu"><span class="hfu-what">${hz(item.what)}</span>${item.when ? `<span class="hfu-when">${escHtml(item.when)}</span>` : ""}</div>`)
            .join("");
        const impacts = [["Training", parsed.training_impact], ["Nutrition", parsed.nutrition_impact]]
            .filter(([, value]) => value)
            .map(([label, value]) => `<div class="himpact"><span class="lbl">${label}</span><span class="himpact-t">${hz(value)}</span></div>`)
            .join("");
        const createdAt = typeof review.created_at === "string" ? review.created_at : "";
        const when = createdAt ? `Reviewed ${relTime(createdAt)}` : "Reviewed";
        const asOf = latestISO ? `<span class="hpic-asof lbl">As of ${escHtml(humanDate(latestISO))}</span>` : "";
        const refresh = stale
            ? `<button id="hRevBtn" class="hpic-refresh hpic-refresh-stale" title="New results since this review"><span class="hdot hdot-warn"></span>New results — refresh</button>`
            : `<button id="hRevBtn" class="hpic-refresh">↻ refresh</button>`;
        const agent = review.agent ? String(review.agent) : "";
        return `<div class="hpic reveal" style="${stagger(0)}">
    <span class="lbl">Your picture</span>
    ${parsed.headline ? `<div class="hpic-headline">${hz(parsed.headline)}</div>` : ""}
    ${asOf}
    ${focus ? `<span class="hpic-sub lbl">This week's focus</span><div class="hfocus-list">${focus}</div>` : ""}
    ${watch ? `<span class="hpic-sub lbl">Watchlist</span><div class="hwatch-list">${watch}</div>` : ""}
    ${wins ? `<span class="hpic-sub lbl">Going well</span><ul class="hwins">${wins}</ul>` : ""}
    ${followups ? `<span class="hpic-sub lbl">Follow-ups</span><div class="hfu-list">${followups}</div>` : ""}
    ${impacts ? `<div class="himpacts">${impacts}</div>` : ""}
    ${String(errorHtml || "")}
    <div class="hpic-foot">
      <span class="hpic-when">${escHtml(when)}${agent ? ` · ${escHtml(agent)}` : ""}</span>
      ${refresh}
    </div>
  </div>`;
    }
    const CAIRN_HEALTH_PICTURE = {
        parsedReview,
        healthDotClass,
        reviewBusyHtml,
        healthHeroHtml,
        buildPictureHtml,
        reviewHtml,
    };
    Object.assign(globalThis, { CairnHealthPicture: CAIRN_HEALTH_PICTURE });
    if (typeof window !== "undefined") {
        window.CairnHealthPicture = CAIRN_HEALTH_PICTURE;
    }
})();
})();
